        return new ReservationResponse(
                r.getId(),
                r.getRoomNumber(),
                r.getGuestName(),
                r.getGuestEmail(),
                r.getGuestCpf(),
                DateHelper.formatDateIso(r.getCheckIn()),
                DateHelper.formatDateIso(r.getCheckOut()),
                r.getGuests(),
                r.getRatePlan().toString(),
                r.getNights(),
                r.getSubtotal(),
                r.getDiscount(),
                r.getTotal(),
                r.getStatus().toString(),
                r.getAmountPaid(),
                r.getRefund()
